// The five native AGH tools (T06).
//
// Contract highlights, all enforced here rather than documented as hopes:
//
//   * parameters are real TypeBox schemas (kind-tagged, closed objects) and
//     every tool writes all eight ToolMeta keys;
//   * no tool accepts a path, a script, a scene object, a hole coordinate, an
//     environment object or any identity field - run ids are generated by the
//     plugin, candidate ids by the run store, task ids come from the prepared
//     workspace's registered task directory;
//   * writing tools are declared as writing (`isReadOnly: false`,
//     `replay: 'never'`, `isDestructive: false`, `requiresApproval: 'always'`)
//     and only `fitplate_get_run` is a pure read. Approval is demanded on
//     every write so the Host's approval handler - the authorized driver runs
//     it - is a real, observable gate (F04 injects there), while the honest
//     destructive flag stays false: these tools publish new immutable
//     versions, they do not destroy existing ones;
//   * every side effect goes through `toolCtx.exec` into the controlled Python
//     bridge; reads go through `toolCtx.fs`; the plugin holds no state.

import { array, bool, int, literal, num, object, str } from './typebox.mjs'
import { clearanceFacts, clearanceFactLines, deliveryFacts } from './report-facts.mjs'
import { USER_FLOW_GUIDANCE } from './user-guidance.mjs'
import {
  CANDIDATE_ID_PATTERN,
  PluginError,
  REPORT_ID_PATTERN,
  RUN_ID_PATTERN,
  TASK_ID_PATTERN,
  businessRefusal,
  callBridge,
  executionError,
  newRunId,
  readRunManifest,
  readRegisteredFile,
  sessionIdentity,
} from './run-store.mjs'

const SCHEMA_VERSION = '1.0'
const TOOL_PREFIX = 'fitplate_'

/**
 * The DesignSpec a model submits. `sensor_pose` is the one thing only the caller can choose
 * (the task grants an *allowed range*, never a position); `schema_version`/`task_id`/
 * `task_revision` may be omitted and are then bound from the frozen run, and a supplied value
 * is still checked against this schema and the run before anything is built - an optional field
 * with a `const` rejects a wrong or null value exactly like the old required one (verified
 * against the host's own TypeBox `Value` checker), so omitting is a convenience, never a way to
 * smuggle a different identity past the bridge.
 */
const designSpecSchema = object(
  {
    schema_version: literal(SCHEMA_VERSION, { description: 'optional; must be "1.0" when supplied, otherwise taken from the frozen run' }),
    task_id: str({ pattern: TASK_ID_PATTERN.source, maxLength: 64, description: 'optional; bound from the frozen run when omitted, and must match it when supplied' }),
    task_revision: int({ minimum: 1, maximum: 1000, description: 'optional; bound from the frozen run when omitted, and must match it when supplied' }),
    plate: object({
      width: num({ minimum: 1, maximum: 2000 }),
      height: num({ minimum: 1, maximum: 2000 }),
      thickness: num({ minimum: 1, maximum: 2000 }),
    }),
    sensor_pose: object(
      {
        center: array(num({ minimum: -10000, maximum: 10000 }), { minItems: 2, maxItems: 2 }),
        rotation_deg: num({ minimum: -360, maximum: 360 }),
      },
      { required: ['center', 'rotation_deg'] },
    ),
    note: str({ minLength: 1, maxLength: 512 }),
  },
  { required: ['sensor_pose'] },
)

const runIdSchema = str({ pattern: RUN_ID_PATTERN.source, maxLength: 128 })
const candidateIdSchema = str({ pattern: CANDIDATE_ID_PATTERN.source, maxLength: 8 })

const WRITE_META = (wallMs) => ({
  isReadOnly: false,
  isDestructive: false,
  isConcurrencySafe: false,
  isOpenWorld: false,
  replay: 'never',
  costHint: { wallMs },
  deferLoading: false,
  // Every write asks for approval. The authorized local driver answers with
  // its own SDK onPermissionRequest handler (which auto-allows exactly these
  // five tools); the gate itself stays real and observable for the host, and
  // a session without that handler is asked, never silently allowed.
  requiresApproval: 'always',
})

const READ_META = (wallMs) => ({
  isReadOnly: true,
  isDestructive: false,
  isConcurrencySafe: true,
  isOpenWorld: false,
  replay: 'safe',
  costHint: { wallMs },
  deferLoading: false,
  requiresApproval: 'never',
})

// ---------------------------------------------------------------------------
// Result shaping
// ---------------------------------------------------------------------------

const text = (value) => [{ type: 'text', text: value }]

function okResult(tool, payload, summary) {
  return {
    content: text(summary),
    structured: { schema_version: SCHEMA_VERSION, tool, ok: true, ...payload },
  }
}

// Business refusal statuses whose `detail` may be rendered to the model. Anything else keeps the
// status line only: the detail of an unknown kind (or an ERROR) could carry arbitrary remote
// objects, and it is never rewritten into a proof-like label.
const DETAIL_STATUSES = new Set([
  'NEEDS_INPUT', 'INFEASIBLE', 'INVALID_SPEC', 'STALE_INPUT', 'LOCKED_CONSTRAINT_CHANGED',
  'DUPLICATE_CANDIDATE', 'BUDGET_EXHAUSTED', 'RUN_EXISTS', 'CANDIDATE_EXISTS', 'CANDIDATE_NOT_FOUND',
  'RUN_NOT_FOUND', 'UNKNOWN_ARTIFACT', 'ARTEFACT_HASH_MISMATCH', 'MESH_BINDING_MISMATCH',
])
const REFUSAL_LABEL = {
  NEEDS_INPUT: '程序判定：缺输入（NEEDS_INPUT）——先补齐下列字段，尚未建模；不要猜测数值或版本',
  INFEASIBLE: '程序判定：可证明无解（INFEASIBLE）——下列为程序给出的证明，只解释它、不要外推未验证的放宽方案',
}

/** Whitelisted, bounded rendering of a business refusal's own detail. */
function refusalDetailLines(error) {
  const detail = error?.detail
  if (!detail || typeof detail !== 'object' || !DETAIL_STATUSES.has(error?.status)) return []
  const lines = []
  if (Array.isArray(detail.issues)) {
    for (const issue of detail.issues.slice(0, MAX_REFUSAL_ITEMS)) {
      if (!issue || typeof issue !== 'object') continue
      const path = typeof issue.path === 'string' ? boundedText(issue.path, 96) : '?'
      const code = typeof issue.code === 'string' ? boundedText(issue.code, 64) : '?'
      const message = typeof issue.message === 'string' ? ` — ${boundedText(issue.message, 160)}` : ''
      lines.push(`  ${path} [${code}]${message}`)
    }
  }
  if (Array.isArray(detail.missing_paths)) {
    const paths = detail.missing_paths
      .filter((item) => typeof item === 'string')
      .slice(0, MAX_REFUSAL_ITEMS)
      .map((item) => boundedText(item, 96))
    if (paths.length) lines.push(`  missing_paths: ${paths.join(', ')}${detail.missing_paths.length > paths.length ? ' …' : ''}`)
  }
  if (Array.isArray(detail.findings)) {
    for (const finding of detail.findings.slice(0, MAX_REFUSAL_ITEMS)) {
      if (!finding || typeof finding !== 'object') continue
      const kind = typeof finding.kind === 'string' ? boundedText(finding.kind, 64) : 'finding'
      const objects = Array.isArray(finding.objects)
        ? finding.objects.filter((item) => typeof item === 'string').slice(0, 6).join(', ')
        : ''
      const scalars = []
      for (const [key, value] of Object.entries(finding)) {
        if (key === 'kind' || key === 'objects' || scalars.length >= 6) continue
        const rendered = boundedScalar(value)
        if (rendered !== null) scalars.push(`${key}=${rendered}`)
      }
      lines.push(`  ${kind}${objects ? ` objects: ${objects}` : ''}${scalars.length ? ` — ${scalars.join(', ')}` : ''}`)
    }
  }
  return lines
}

/**
 * A business refusal's observable text: the status line plus - for whitelisted business
 * statuses - the real, bounded detail the program produced (issues / missing_paths / findings).
 * The structured result stays exactly as before; the status is never rewritten (an ERROR or an
 * unknown status is never presented as INFEASIBLE).
 */
export function refusalResult(tool, error) {
  const label = REFUSAL_LABEL[error?.status]
  const content = [
    `${tool}: ${error.status} - ${boundedText(error.message ?? 'refused', 240)}`,
    ...(label ? [label] : []),
    ...refusalDetailLines(error),
  ].join('\n')
  return {
    content: text(content),
    structured: {
      schema_version: SCHEMA_VERSION,
      tool,
      ok: false,
      status: error.status,
      code: error.code,
      message: error.message,
      ...(error.detail ? { detail: error.detail } : {}),
    },
  }
}

function errorResult(tool, error) {
  return {
    isError: true,
    content: text(`${tool}: ${error.code} - ${error.message}`),
    structured: {
      schema_version: SCHEMA_VERSION,
      tool,
      ok: false,
      status: 'ERROR',
      code: error.code,
      message: error.message,
      ...(error.detail ? { detail: error.detail } : {}),
    },
  }
}

/** Run one tool body, mapping the plugin's error taxonomy onto tool results. */
async function guarded(tool, body) {
  try {
    return await body()
  } catch (error) {
    if (error instanceof PluginError) {
      return error.kind === 'business' ? refusalResult(tool, error) : errorResult(tool, error)
    }
    const message = error instanceof Error ? error.message : String(error)
    return errorResult(tool, executionError('INTERNAL_ERROR', `unexpected failure: ${message}`))
  }
}

/** Rendered into tool summaries; exported so the unit labels themselves are regression-tested. */
export const budgetLine = (budget) =>
  budget && typeof budget === 'object'
    ? `budget: ${Math.round(Number(budget.spent_ms ?? 0))}/${Number(budget.limit_ms ?? 0)} ms · ` +
      `commands=${Number(budget.commands ?? 0)}（累计命令数，单独计数） · ` +
      `max_candidates=${Number(budget.max_candidates ?? 0)}（候选上限；实际已发布候选数以 run store 为准，不用命令数推算）`
    : 'budget: unknown'

/** Canonical G01–G08 display names, kept in sync with the panel (scene-model CHECK_TITLES). */
export const CHECK_TITLES = Object.freeze({
  G01: '实体有效性',
  G02: '板体尺寸与姿态',
  G03: '底座通孔',
  G04: '传感器孔组 / 位姿',
  G05: '孔边与孔间材料',
  G06: '装配自由空间',
  G07: '固定条件保持',
  G08: '导出一致性',
})

const MAX_MEASURED_FIELDS = 6
const MAX_REQUIRED_FIELDS = 4
const MAX_REFUSAL_ITEMS = 6

/** Bound one scalar for tool text; nested/oversized values are omitted (null), never invented. */
const boundedScalar = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? String(Math.round(value * 1e6) / 1e6) : null
  if (typeof value === 'boolean') return String(value)
  if (typeof value === 'string') return value.length <= 64 ? value : `${value.slice(0, 61)}…`
  if (Array.isArray(value) && value.length > 0 && value.every((item) => typeof item === 'number')) {
    return `[${value.slice(0, 4).join(', ')}]`
  }
  return null
}

/** Collapse whitespace and cap length; the only string shape that ever reaches tool text. */
const boundedText = (value, max = 200) => {
  const flat = String(value).replace(/\s+/g, ' ').trim()
  return flat.length <= max ? flat : `${flat.slice(0, max - 1)}…`
}

/** `key=value` pairs for whitelisted keys the source actually carries, in priority order. */
const fieldPairs = (source, priority, max) => {
  const parts = []
  if (!source || typeof source !== 'object') return parts
  for (const key of priority) {
    if (parts.length >= max) break
    if (!Object.hasOwn(source, key)) continue
    const rendered = boundedScalar(source[key])
    if (rendered !== null) parts.push(`${key}=${rendered}`)
  }
  return parts
}

/** Measured keys worth showing, most diagnostic first (all read from the current bound report). */
const MEASURED_PRIORITY = [
  'worst_pair', 'worst_pair_distance_mm', 'worst_pair_volume_mm3', 'minimum_free_clearance_mm',
  'minimum_clearance_mm', 'failing_pairs', 'maximum_intersection_volume_mm3', 'borderline_pairs',
  'pairs_checked', 'minimum_edge_ligament_mm', 'tightest_edge_hole', 'minimum_hole_ligament_mm',
  'tightest_hole_pair', 'unexplained_holes', 'holes_checked', 'derived_center_x_mm', 'derived_center_y_mm',
  'pose_solutions', 'worst_pattern_deviation_mm', 'max_measured_diameter_mm', 'min_measured_diameter_mm',
  'hole_count', 'volume_mm3', 'solid_count', 'shell_count', 'free_shape_count', 'size_x_mm', 'size_y_mm', 'size_z_mm',
]
const REQUIRED_PRIORITY = [
  'minimum_free_clearance_mm', 'minimum_edge_ligament_mm', 'minimum_hole_ligament_mm',
  'support_contact_allows_zero_distance', 'support_contact_allows_penetration',
  'interference_volume_epsilon_mm3', 'extra_holes_allowed', 'dimensional_tolerance_mm',
]

/**
 * One bounded block per G01–G08 check: accurate name, status, reason, objects and the key
 * measured/required values the *current bound report* actually carries. Unknown values are
 * printed as null, never invented; `minimum_clearance_mm` (legacy, includes the allowed support
 * contact) is explicitly labelled as not being a free-clearance summary.
 */
export function validateCheckSummaryLines(report) {
  const checks = Array.isArray(report?.checks) ? report.checks : []
  const lines = []
  for (const check of checks) {
    const id = typeof check?.id === 'string' ? check.id : '?'
    const title = CHECK_TITLES[id] ?? ''
    const status = check?.status ?? 'UNKNOWN'
    const objects = Array.isArray(check?.objects) ? check.objects.filter((item) => typeof item === 'string') : []
    lines.push(
      `  ${id}${title ? ` ${title}` : ''} ${status}${check?.reason_code ? ` (${check.reason_code})` : ''} — ${id === 'G06' ? '检查覆盖范围' : 'objects'}: ${objects.join(', ') || 'null'}`,
    )
    if (id === 'G06') lines.push(...clearanceFactLines(clearanceFacts(check)).map((line) => `      ${line}`))
    if (id === 'G05') {
      const boundaries = ['left', 'right', 'bottom', 'top'].map((side) => ({ side, value: check?.measured?.[`minimum_${side}_edge_ligament_mm`] }))
      if (boundaries.every(({ value }) => typeof value === 'number' && Number.isFinite(value))) {
        lines.push(`      当前实测各边最小孔边材料(mm): ${boundaries.map(({ side, value }) => `${side}=${boundedScalar(value)}`).join(', ')}`)
        lines.push('      边界关系：矩形板左下原点固定且孔位/孔径不变时，单改 width 只移动右边，单改 height 只移动上边；左/下孔边材料及孔间材料不会因此增加。整改须关联当前限制边/对象；这不是新修订的验证结果，也不新增修改许可。')
      }
    }
    if (typeof check?.note === 'string') lines.push(`      note: ${boundedText(check.note, 160)}`)
    const measured = fieldPairs(check?.measured, MEASURED_PRIORITY, MAX_MEASURED_FIELDS)
    if (measured.length) {
      const legacyClearance =
        Object.hasOwn(check?.measured ?? {}, 'minimum_clearance_mm') &&
        !Object.hasOwn(check?.measured ?? {}, 'minimum_free_clearance_mm') &&
        check?.required?.support_contact_allows_zero_distance === true
      lines.push(
        `      measured: ${measured.join(', ')}${legacyClearance ? '（minimum_clearance_mm 是旧字段、含允许支撑接触；本报告没有独立自由间隙摘要，不能当自由间隙）' : ''}`,
      )
    } else if (status !== 'PASS') {
      lines.push('      measured: null（报告未提供）')
    }
    if (status !== 'PASS' || id === 'G06') {
      const required = fieldPairs(check?.required, REQUIRED_PRIORITY, MAX_REQUIRED_FIELDS)
      lines.push(`      required: ${required.length ? required.join(', ') : 'null（报告未提供）'}`)
    }
  }
  return lines
}

/**
 * Selected-candidate lines for `fitplate_get_run`, built ONLY from the run manifest's own
 * fields. When the manifest carries a per-check summary projection (id/status/objects) it is
 * shown and labelled as a projection - never dressed up as per-check measurements.
 */
export function getRunSelectedLines(manifest, candidateId) {
  const selected = manifest?.candidates?.[candidateId]
  if (!selected) return []
  const report = selected.report ?? null
  const lines = [
    `selected ${candidateId}: status=${selected.status} report=${report?.report_id ?? 'null'} overall=${report?.overall ?? 'null'} report_file_sha256=${report?.report_file_sha256 ?? 'null'}`,
  ]
  const checks = Array.isArray(report?.checks) ? report.checks : []
  if (checks.length) {
    lines.push('report checks（来自 run manifest 的摘要投影：只有 id/status/objects，逐项实测值不在 manifest 中）:')
    for (const check of checks.slice(0, 12)) {
      if (!check || typeof check !== 'object') continue
      const id = typeof check.id === 'string' ? check.id : '?'
      const objects = Array.isArray(check.objects) ? check.objects.filter((item) => typeof item === 'string').slice(0, 6) : []
      lines.push(
        `  ${id}${CHECK_TITLES[id] ? ` ${CHECK_TITLES[id]}` : ''} ${check.status ?? 'UNKNOWN'}${check.reason_code ? ` (${check.reason_code})` : ''} — ${id === 'G06' ? '检查覆盖范围（逐项实测值须读取绑定报告）' : 'objects'}: ${objects.join(', ') || 'null'}`,
      )
    }
  } else if (report) {
    lines.push('report checks: null（manifest 未含逐项摘要；详细实测值以 validate 的当次报告为准）')
  }
  const exportEntry = Array.isArray(manifest?.exports?.[candidateId]) ? manifest.exports[candidateId].at(-1) : null
  if (exportEntry) lines.push(`export: ${exportEntry.export_id ?? 'unknown'} failed=${exportEntry.failed === true} report=${exportEntry.report_id ?? 'null'}`)
  return lines
}

/**
 * Timeout for one bridge call: bounded by the configured per-command budget and
 * by the Host's own call deadline, so the bridge gets a chance to answer with a
 * proper envelope (or to be killed *by the plugin's request*, not mid-publish).
 */
function execTimeoutFor(ctx, config, { long }) {
  const wanted = long ? config.budget.commandTimeoutMs + 5000 : 15000
  const hostDeadline = typeof ctx.timeoutMs === 'number' && ctx.timeoutMs > 0 ? ctx.timeoutMs - 250 : wanted
  return Math.max(1000, Math.min(wanted, hostDeadline))
}

/** Fail fast when a run manifest exists but belongs to a different session/workspace. */
async function requireOwnRun(ctx, config, runId, session) {
  const manifest = await readRunManifest(ctx, config, runId)
  if (!manifest) {
    throw businessRefusal('RUN_NOT_FOUND', `run ${runId} does not exist in this workspace`, { status: 'STALE_INPUT' })
  }
  const owner = manifest.owner ?? {}
  if (owner.session_key !== session.key || owner.workspace_root !== ctx.cwd) {
    throw businessRefusal(
      'SESSION_MISMATCH',
      'this run belongs to another session or workspace; runs are never shared across sessions',
      { status: 'STALE_INPUT' },
    )
  }
  return manifest
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

export function buildTools({ config, log }) {
  const tools = []
  const notice = (message) => log?.info?.(message)

  tools.push({
    name: `${TOOL_PREFIX}load_task`,
    description: [
      'Freeze one registered FitPlate task into a new run.',
      'Input: task_id (the folder name under the prepared workspace input/tasks directory) and its revision.',
      'Creates runs/<run_id>/ with frozen copies of task.json and the scene it pins, a manifest and an event log,',
      'and returns the frozen constraints (plate dimensions, base holes, sensor envelope, allowed ranges, tolerances)',
      'plus the input provenance recorded in the frozen task (kind/source/review_status, or unknown when it carries',
      'none) and the verification scope: software geometry on these frozen inputs only - it is not a physical or',
      'official verification, and a declared source is never upgraded to vendor/official.',
      'Missing information returns NEEDS_INPUT; a stale revision returns STALE_INPUT; nothing else is accepted -',
      'this tool never takes a file path, a scene object, a hole coordinate or an identity.',
      'Next step: build a candidate with fitplate_build_candidate using the returned run_id.',
    ].join(' '),
    parameters: object(
      {
        task_id: str({ pattern: TASK_ID_PATTERN.source, maxLength: 64 }),
        revision: int({ minimum: 1, maximum: 1000 }),
      },
      { required: ['task_id', 'revision'] },
    ),
    meta: WRITE_META(config.budget.commandTimeoutMs),
    async execute(args, ctx) {
      return guarded(`${TOOL_PREFIX}load_task`, async () => {
        sessionIdentity(ctx)
        const runId = newRunId()
        const { envelope } = await callBridge(
          ctx,
          config,
          'load_task',
          { task_id: args.task_id, revision: args.revision, run_id: runId },
          { runId, timeoutMs: execTimeoutFor(ctx, config, { long: false }) },
        )
        if (!envelope.ok) {
          throw businessRefusal(envelope.code, envelope.message ?? 'the task could not be loaded', {
            status: envelope.status ?? 'INVALID_SPEC',
            detail: envelope.detail,
          })
        }
        const data = envelope.data ?? {}
        const summary = [
          `${TOOL_PREFIX}load_task: run ${data.run_id} frozen at task revision ${data.task_revision} (${data.status})`,
          ...(data.reused === true
            ? [
                `this session already opened run ${data.run_id} for exactly this task/revision/input: reusing it` +
                  ` (status ${data.status}${Array.isArray(data.candidates) && data.candidates.length ? `, ${data.candidates.length} candidate(s): ${data.candidates.map((row) => `${row.candidate_id}${row.overall ? `:${row.overall}` : ''}`).join(', ')}` : ''})` +
                  ' - continue in this run; the candidate budget is not reset',
              ]
            : []),
          `plate ${data.plate.width}x${data.plate.height}x${data.plate.thickness} mm, locked=[${(data.plate.locked ?? []).join(', ')}]`,
          `sensor center allowed x[${data.sensor.allowed_center_x.min},${data.sensor.allowed_center_x.max}] y[${data.sensor.allowed_center_y.min},${data.sensor.allowed_center_y.max}]`,
          `frozen sensor geometry (input, not measured): body_size_mm=${JSON.stringify(data.sensor.body_size ?? null)}, hole_offsets_mm=${JSON.stringify(data.sensor.hole_offsets ?? null)}, hole_diameter_mm=${JSON.stringify(data.sensor.hole_diameter ?? null)}`,
          `frozen scene geometry (input, not measured): frame=${data.scene?.frame ?? 'unknown'}, units=${data.scene?.units ?? 'unknown'}, objects=${JSON.stringify(data.scene?.objects ?? null)}, support_contacts=${JSON.stringify(data.scene?.support_contacts ?? null)}; local_* coordinates follow the sensor pose, absolute_z_range does not`,
          `requirements: clearance>=${data.requirements.minimum_free_clearance}, edge ligament>=${data.requirements.minimum_edge_ligament}, hole ligament>=${data.requirements.minimum_hole_ligament}`,
          `input provenance: kind=${data.input_provenance?.kind ?? 'unknown'}${data.input_provenance?.source ? ` source=${data.input_provenance.source}` : ''}${data.input_provenance?.review_status ? ` review_status=${data.input_provenance.review_status}` : ''}`,
          `scope: ${data.verification_scope ?? 'software_geometry_only'} - software geometry on these frozen inputs only; no physical assembly, material strength, printing tolerance or sensor performance was measured, and a declared source is never an official/vendor verification`,
          budgetLine(data.budget),
          'next: fitplate_build_candidate(run_id, design_spec:{sensor_pose:{center:[x,y], rotation_deg:0}}) - the frozen run already binds task_id/revision',
        ].join('\n')
        return okResult(`${TOOL_PREFIX}load_task`, { status: data.status, ...data }, summary)
      })
    },
  })

  tools.push({
    name: `${TOOL_PREFIX}build_candidate`,
    description: [
      'Build one candidate plate from a DesignSpec inside an existing run and publish it as an immutable version.',
      'Minimum call: {run_id, design_spec:{sensor_pose:{center:[x,y], rotation_deg:0}}} - the run already froze the',
      'task, so design_spec.task_id/task_revision/schema_version and the outer task_revision may be omitted and are',
      'bound from that frozen run. A supplied task_id/task_revision is still compared against the frozen run and a',
      'mismatch is refused (STALE_INPUT), never silently corrected; a wrong schema_version is rejected by the tool',
      'schema itself, not by that comparison. sensor_pose is always required: the task grants only an',
      'allowed range: the model selects and states a concrete candidate center within it; no extra user coordinate is needed. design_spec stays closed;',
      'plate is optional, and whichever of its dimensions you give must be permitted and is checked - any dimension',
      'you leave out is taken from the frozen task, while explicitly sending a changed locked value is still refused.',
      'Optional parent_candidate_id',
      'extends the latest version. The tool builds the actual STEP/STL artefacts plus a real tessellated preview and',
      'records their hashes. It never overwrites a version: the next version id (v001, v002, ...) is assigned by the',
      'run store. Locked value changes return LOCKED_CONSTRAINT_CHANGED, a stale revision STALE_INPUT, an out-of-range',
      'value INVALID_SPEC, a repeated identical DesignSpec DUPLICATE_CANDIDATE, and an exhausted budget',
      'BUDGET_EXHAUSTED (never "infeasible"). Generation failure is an execution error (BUILD_ERROR), not a geometry',
      'verdict. Next step: fitplate_validate_candidate.',
    ].join(' '),
    parameters: object(
      {
        run_id: runIdSchema,
        task_revision: int({ minimum: 1, maximum: 1000, description: 'optional; bound from the frozen run when omitted, and must match it when supplied' }),
        design_spec: designSpecSchema,
        parent_candidate_id: candidateIdSchema,
      },
      { required: ['run_id', 'design_spec'] },
    ),
    meta: WRITE_META(config.budget.commandTimeoutMs),
    async execute(args, ctx) {
      return guarded(`${TOOL_PREFIX}build_candidate`, async () => {
        const session = sessionIdentity(ctx)
        // The run is the only trusted source of the task identity: the owner check happens first,
        // and the frozen revision then fills ONLY fields the caller left undefined. A supplied
        // value is passed through untouched, so the bridge's own strict comparison still rejects
        // a wrong one - a default may complete an omission, never overwrite a statement.
        const manifest = await requireOwnRun(ctx, config, args.run_id, session)
        const designSpec = { ...args.design_spec }
        if (designSpec.schema_version === undefined) designSpec.schema_version = SCHEMA_VERSION
        if (designSpec.task_id === undefined) designSpec.task_id = manifest.task_id
        if (designSpec.task_revision === undefined) designSpec.task_revision = manifest.task_revision
        const taskRevision = args.task_revision === undefined ? manifest.task_revision : args.task_revision
        const { envelope } = await callBridge(
          ctx,
          config,
          'build_candidate',
          {
            run_id: args.run_id,
            task_revision: taskRevision,
            design_spec: designSpec,
            ...(args.parent_candidate_id ? { parent_candidate_id: args.parent_candidate_id } : {}),
          },
          { runId: args.run_id, timeoutMs: execTimeoutFor(ctx, config, { long: true }) },
        )
        if (!envelope.ok) {
          throw businessRefusal(envelope.code, envelope.message ?? 'the candidate was not built', {
            status: envelope.status ?? 'INVALID_SPEC',
            detail: envelope.detail,
          })
        }
        const data = envelope.data ?? {}
        if (!CANDIDATE_ID_PATTERN.test(String(data.candidate_id))) {
          throw executionError('IDENTITY_MISMATCH', 'the run store returned an unusable candidate id')
        }
        const summary = [
          `${TOOL_PREFIX}build_candidate: published ${data.candidate_id} in run ${data.run_id} (parent=${data.parent_candidate_id ?? 'none'})`,
          `step_sha256=${data.step_sha256}`,
          `preview: ${data.preview_triangles} triangles, ${data.preview_mesh_bytes} bytes; build took ${Math.round(data.duration_ms)} ms`,
          budgetLine(data.budget),
          'note: the generator self-check is not acceptance evidence - measure the artefact next',
          `next: fitplate_validate_candidate(run_id=${data.run_id}, candidate_id=${data.candidate_id})`,
        ].join('\n')
        return okResult(`${TOOL_PREFIX}build_candidate`, { status: data.status, ...data }, summary)
      })
    },
  })

  tools.push({
    name: `${TOOL_PREFIX}validate_candidate`,
    description: [
      'Measure the actual STEP artefact of one candidate in an independent process and record a G01-G08 report.',
      'Input: run_id and candidate_id. The validator re-imports the stored STEP file, re-measures the plate, holes,',
      'ligaments and assembly clearances, and compares them with the frozen task and scene - it never trusts the',
      'generator, the DesignSpec or an earlier report. Output: report_id, overall (PASS/FAIL/UNKNOWN/BORDERLINE)',
      'and the per-check results. A measured constraint failure is a normal structured result (FAIL), not a tool',
      'error; UNKNOWN or BORDERLINE can never be reported as PASS; unrecoverable measurement problems are execution',
      'errors and never turn into a PASS. Next step: fitplate_export_package for a passing candidate.',
    ].join(' '),
    parameters: object(
      { run_id: runIdSchema, candidate_id: candidateIdSchema },
      { required: ['run_id', 'candidate_id'] },
    ),
    meta: WRITE_META(config.budget.commandTimeoutMs),
    async execute(args, ctx) {
      return guarded(`${TOOL_PREFIX}validate_candidate`, async () => {
        const session = sessionIdentity(ctx)
        const manifest = await requireOwnRun(ctx, config, args.run_id, session)
        const { envelope } = await callBridge(
          ctx,
          config,
          'validate_candidate',
          { run_id: args.run_id, candidate_id: args.candidate_id },
          { runId: args.run_id, candidateId: args.candidate_id, timeoutMs: execTimeoutFor(ctx, config, { long: true }) },
        )
        if (!envelope.ok) {
          throw businessRefusal(envelope.code, envelope.message ?? 'the candidate could not be validated', {
            status: envelope.status ?? 'INVALID_SPEC',
            detail: envelope.detail,
          })
        }
        const data = envelope.data ?? {}
        const report = data.report ?? {}
        const facts = deliveryFacts(report, {
          candidateId: args.candidate_id,
          taskRevision: manifest.task_revision ?? null,
          stepSha256: manifest.candidates?.[args.candidate_id]?.hashes?.step_sha256 ?? null,
          reportId: data.report_id ?? null,
        })
        if (facts.bindingState === 'stale') {
          throw businessRefusal('REPORT_BINDING_MISMATCH', 'the validation report does not bind the current candidate, task revision, STEP and report id', {
            status: 'STALE_INPUT', detail: { mismatched: facts.mismatched },
          })
        }
        const failed = Array.isArray(data.failed_checks) ? data.failed_checks : []
        const checkLines = facts.bindingState === 'current'
          ? validateCheckSummaryLines(report) : ['报告绑定信息不完整；实测摘要未核实。']
        const failedById = new Map((report.checks ?? []).filter((check) => check && typeof check === 'object').map((check) => [check.id, check]))
        const summary = [
          `${TOOL_PREFIX}validate_candidate: ${data.candidate_id} in run ${data.run_id} -> ${data.overall} (report ${data.report_id})`,
          `validator ${report.validator_version ?? 'unknown'} on step_sha256=${report.hashes?.step_sha256 ?? 'unknown'}`,
          ...checkLines,
          failed.length
            ? `failed: ${failed
                .map((check) => {
                  const detail = failedById.get(check.id)
                  const objects = Array.isArray(detail?.objects) ? ` ${check.id === 'G06' ? 'check scope' : 'objects'}: ${detail.objects.join(', ')}` : ''
                  const pair = check.id === 'G06' ? clearanceFacts(detail).failurePair : null
                  return `${check.id}${CHECK_TITLES[check.id] ? ` ${CHECK_TITLES[check.id]}` : ''}:${check.reason_code ?? 'UNKNOWN'}${objects}${pair ? ` failure pair: ${pair}` : ''}`
                })
                .join('；')} - adjust design_spec and build a revision`
            : facts.accepted
              ? 'every check passed - export the package to bind the evidence'
              : '报告尚未构成当前版本的完整通过证据；请核对绑定、逐项状态与错误，不得宣称交付通过。',
          budgetLine(data.budget),
        ].join('\n')
        return okResult(
          `${TOOL_PREFIX}validate_candidate`,
          {
            status: data.status,
            run_id: data.run_id,
            candidate_id: data.candidate_id,
            task_revision: data.task_revision,
            overall: data.overall,
            report_id: data.report_id,
            report,
            delivery_facts: facts,
            failed_checks: failed,
            evidence_summary: data.evidence_summary,
            validator_code_sha256: data.validator_code_sha256,
            duration_ms: data.duration_ms,
            budget: data.budget,
          },
          summary,
        )
      })
    },
  })

  tools.push({
    name: `${TOOL_PREFIX}get_run`,
    description: [
      'Read the current state of one run from disk: status, task revision, the immutable version list with their',
      'report summaries, the budget and any exports. Input: run_id and optionally candidate_id for one version in',
      'detail. Read-only and replay-safe; it never writes, never validates and never calls the geometry programs.',
      'Use it after a revision or before exporting to see exactly which version is passing.',
    ].join(' '),
    parameters: object({ run_id: runIdSchema, candidate_id: candidateIdSchema }, { required: ['run_id'] }),
    meta: READ_META(1000),
    async execute(args, ctx) {
      return guarded(`${TOOL_PREFIX}get_run`, async () => {
        const session = sessionIdentity(ctx)
        const manifest = await requireOwnRun(ctx, config, args.run_id, session)
        const versions = Object.keys(manifest.candidates ?? {})
          .sort()
          .map((candidateId) => {
            const entry = manifest.candidates[candidateId]
            return {
              candidate_id: candidateId,
              parent_candidate_id: entry.parent_candidate_id ?? null,
              status: entry.status,
              created_at: entry.created_at,
              step_sha256: entry.hashes?.step_sha256,
              overall: entry.report?.overall ?? null,
              report_id: entry.report?.report_id ?? null,
            }
          })
        const selected = args.candidate_id ? manifest.candidates?.[args.candidate_id] : undefined
        if (args.candidate_id && !selected) {
          throw businessRefusal('CANDIDATE_NOT_FOUND', `candidate ${args.candidate_id} does not exist in run ${args.run_id}`, {
            status: 'STALE_INPUT',
          })
        }
        const summaryLines = [
          `${TOOL_PREFIX}get_run: ${manifest.run_id} status=${manifest.status} task=${manifest.task_id}@r${manifest.task_revision}`,
          ...versions.map(
            (version) =>
              `  ${version.candidate_id} ${version.status}${version.overall ? ` overall=${version.overall}` : ''}${
                version.parent_candidate_id ? ` parent=${version.parent_candidate_id}` : ''
              }`,
          ),
          versions.length ? '' : '  (no candidate versions yet)',
          budgetLine(manifest.budget),
        ].filter(Boolean)
        if (selected) {
          summaryLines.push(...getRunSelectedLines(manifest, args.candidate_id))
        }
        return okResult(
          `${TOOL_PREFIX}get_run`,
          {
            status: manifest.status,
            run_id: manifest.run_id,
            task_id: manifest.task_id,
            task_revision: manifest.task_revision,
            created_at: manifest.created_at,
            frozen: manifest.frozen,
            budget: manifest.budget,
            versions,
            exports: manifest.exports ?? {},
            ...(selected
              ? {
                  candidate: {
                    candidate_id: args.candidate_id,
                    status: selected.status,
                    design_sha256: selected.design_sha256,
                    design_summary: selected.design_summary,
                    hashes: selected.hashes,
                    report: selected.report ?? null,
                    validator_code_sha256: selected.validator_code_sha256 ?? null,
                  },
                }
              : {}),
          },
          summaryLines.join('\n'),
        )
      })
    },
  })

  tools.push({
    name: `${TOOL_PREFIX}export_package`,
    description: [
      'Export a reproducible bundle for one validated candidate: the STEP/STL/preview artefacts, the frozen task and',
      'scene, the DesignSpec, the validation report and its evidence, plus a manifest with the SHA-256 of every file.',
      'Input: run_id, candidate_id, report_id and allow_failed. The export re-reads the stored report, re-verifies',
      'every artefact hash against the manifest and refuses when the report is stale or describes another artefact.',
      'A report that is not PASS is refused unless allow_failed=true, in which case the bundle is produced and',
      'labelled as a failed/diagnostic export - it must never be presented as accepted.',
      'The bundle also carries the frozen task input provenance (kind/source/review_status, or unknown) and the',
      'verification scope: software geometry on the frozen inputs only - no physical assembly, material strength,',
      'printing tolerance or sensor performance was measured, and the source is not an official/vendor verification.',
    ].join(' '),
    parameters: object(
      {
        run_id: runIdSchema,
        candidate_id: candidateIdSchema,
        report_id: str({ pattern: REPORT_ID_PATTERN.source, maxLength: 128 }),
        allow_failed: bool(),
      },
      { required: ['run_id', 'candidate_id', 'report_id'] },
    ),
    meta: WRITE_META(5000),
    async execute(args, ctx) {
      return guarded(`${TOOL_PREFIX}export_package`, async () => {
        const session = sessionIdentity(ctx)
        const manifest = await requireOwnRun(ctx, config, args.run_id, session)
        const { envelope } = await callBridge(
          ctx,
          config,
          'export_package',
          {
            run_id: args.run_id,
            candidate_id: args.candidate_id,
            report_id: args.report_id,
            allow_failed: args.allow_failed === true,
          },
          { runId: args.run_id, candidateId: args.candidate_id, timeoutMs: execTimeoutFor(ctx, config, { long: true }) },
        )
        if (!envelope.ok) {
          throw businessRefusal(envelope.code, envelope.message ?? 'the export was refused', {
            status: envelope.status ?? 'INVALID_SPEC',
            detail: envelope.detail,
          })
        }
        const data = envelope.data ?? {}
        // Export has already verified the registered files. Read the same report through
        // the bounded, hash-verifying store API; never infer measurements from the design.
        let facts = null
        if (manifest.candidates?.[args.candidate_id]?.report) {
          const { bytes } = await readRegisteredFile(ctx, config, args.run_id, args.candidate_id, 'report.json', { maxBytes: 256 * 1024 })
          facts = deliveryFacts(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)), {
            candidateId: args.candidate_id,
            taskRevision: manifest.task_revision ?? null,
            stepSha256: data.hashes?.step_sha256 ?? null,
            reportId: args.report_id,
          })
        }
        const summary = [
          `${TOOL_PREFIX}export_package: ${data.candidate_id} (report ${data.report_id}, overall ${data.overall}) -> ${data.export_dir}`,
          `failed_export=${data.failed === true}${data.failed === true ? ' - this bundle documents a non-passing candidate' : ''}`,
          ...(facts?.bindingState === 'current' ? clearanceFactLines(facts.clearance) : ['交付测量摘要未核实；请读取当前绑定报告，不得猜测最紧对象对。']),
          `files: ${(data.files ?? []).map((file) => file.name).join(', ')}`,
          `step_sha256=${data.hashes?.step_sha256 ?? 'unknown'}`,
          `validator_code_sha256=${data.validator_code_sha256 ?? 'unknown'}`,
          `input provenance: kind=${data.input_provenance?.kind ?? 'unknown'}${data.input_provenance?.source ? ` source=${data.input_provenance.source}` : ''}${data.input_provenance?.review_status ? ` review_status=${data.input_provenance.review_status}` : ''}`,
          `scope: ${data.verification_scope ?? 'software_geometry_only'} - this bundle proves software geometry on the frozen inputs only; no physical assembly, material strength, printing tolerance or sensor performance was measured, and the input source is not an official/vendor verification`,
          budgetLine(data.budget),
        ].join('\n')
        return okResult(`${TOOL_PREFIX}export_package`, { status: data.status, ...data, delivery_facts: facts }, summary)
      })
    },
  })

  for (const tool of tools) tool.description += USER_FLOW_GUIDANCE
  notice(`fitplate plugin registered ${tools.length} tools`)
  return tools
}
